public static class CreateLevelThreeNeonCourier
{
    private const string ScenePath="Assets/Scenes/Level3_NeonCourier.unity", BackdropPath="Assets/Art/Level3_NeonAlley.jpeg", Mats="Assets/Art/Materials";
    [MenuItem("The Last Memory/Level 3/Create Neon Courier")]
    private static void BuildFromMenu()
    {
        if(EditorApplication.isPlaying){EditorApplication.playModeStateChanged-=AfterPlayMode;EditorApplication.playModeStateChanged+=AfterPlayMode;EditorApplication.isPlaying=false;return;}
        if(!File.Exists(BackdropPath)){EditorUtility.DisplayDialog("Level 3 backdrop missing","Put the supplied neon alley image at Assets/Art/Level3_NeonAlley.jpeg, then run this command again.","OK");return;}
        BuildScene();EditorUtility.DisplayDialog("Level 3 ready","Neon Laser Run is connected after Level 2 and plays FreshmanSound-Fear from Assets/audio.","OK");
    }
    private static void AfterPlayMode(PlayModeStateChange s){if(s!=PlayModeStateChange.EnteredEditMode)return;EditorApplication.playModeStateChanged-=AfterPlayMode;EditorApplication.delayCall+=BuildFromMenu;}
    public static void BuildBatch(){if(!File.Exists(ScenePath)&&File.Exists(BackdropPath))BuildScene();}
    private static void BuildScene()
    {
        EnsureFolder("Assets/Art");EnsureFolder(Mats);EnsureFolder("Assets/Scenes");AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);AssetDatabase.ImportAsset(BackdropPath,ImportAssetOptions.ForceUpdate);
        Scene scene=EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);
        Material road=Lit("L3_WetAsphalt",new Color32(18,23,36,255),new Color(.04f,.08f,.14f)),sidewalk=Lit("L3_Sidewalk",new Color32(37,36,52,255)),building=Lit("L3_AlleyBuildings",new Color32(19,25,42,255));
        Material cyan=Lit("L3_CyanNeon",new Color32(15,180,220,255),new Color(.02f,.8f,1)),pink=Lit("L3_PinkNeon",new Color32(220,25,125,255),new Color(1,.02f,.32f)),red=Lit("L3_SecurityRed",new Color32(190,20,40,255),new Color(1,.01f,.03f)),green=Lit("L3_ExtractionGreen",new Color32(25,185,110,255),new Color(.02f,1,.35f)),gold=Lit("L3_DataDrive",new Color32(35,220,240,255),new Color(.05f,1,1));
        GameObject world=new GameObject("Level3_NeonDistrict");
        Make("Rain Slick Street",PrimitiveType.Cube,world.transform,new Vector3(0,-.35f,29),new Vector3(22,.7f,72),road,true);
        Make("Left Walkway",PrimitiveType.Cube,world.transform,new Vector3(-10.2f,.02f,29),new Vector3(2.3f,.14f,72),sidewalk,true);Make("Right Walkway",PrimitiveType.Cube,world.transform,new Vector3(10.2f,.02f,29),new Vector3(2.3f,.14f,72),sidewalk,true);
        Make("Left Neon Curb",PrimitiveType.Cube,world.transform,new Vector3(-8.95f,.1f,29),new Vector3(.1f,.12f,70),cyan,false);Make("Right Neon Curb",PrimitiveType.Cube,world.transform,new Vector3(8.95f,.1f,29),new Vector3(.1f,.12f,70),pink,false);
        for(int i=0;i<6;i++){float z=4+i*11;Make("Left Tower "+(i+1),PrimitiveType.Cube,world.transform,new Vector3(-14,8,z),new Vector3(7,18,12),building,true);Make("Right Tower "+(i+1),PrimitiveType.Cube,world.transform,new Vector3(14,9,z+2),new Vector3(7,20,12),building,true);Make("Left Sign "+(i+1),PrimitiveType.Cube,world.transform,new Vector3(-10.35f,3.5f,z+1),new Vector3(.16f,3.4f,2.2f),i%2==0?pink:cyan,false);Make("Right Sign "+(i+1),PrimitiveType.Cube,world.transform,new Vector3(10.35f,4,z+5),new Vector3(.16f,4,2.4f),i%2==0?cyan:pink,false);for(int w=0;w<4;w++){float wz=z-3+w*2.3f;Make("Left Window",PrimitiveType.Cube,world.transform,new Vector3(-10.48f,7.2f,wz),new Vector3(.1f,1.1f,.75f),w%2==0?cyan:pink,false);Make("Right Window",PrimitiveType.Cube,world.transform,new Vector3(10.48f,8.2f,wz),new Vector3(.1f,1.1f,.75f),w%2==0?pink:cyan,false);}}
        Texture2D texture=AssetDatabase.LoadAssetAtPath<Texture2D>(BackdropPath);Shader unlit=Shader.Find("Universal Render Pipeline/Unlit");if(unlit==null)unlit=Shader.Find("Unlit/Texture");Material bg=new Material(unlit);if(bg.HasProperty("_BaseMap"))bg.SetTexture("_BaseMap",texture);if(bg.HasProperty("_MainTex"))bg.SetTexture("_MainTex",texture);AssetDatabase.CreateAsset(bg,Mats+"/L3_NeonAlleyBackdrop.mat");GameObject billboard=Make("Reference Neon Alley Backdrop",PrimitiveType.Quad,world.transform,new Vector3(0,23,70),new Vector3(52,88,1),bg,false);billboard.transform.rotation=Quaternion.Euler(0,180,0);
        Make("Street barrier left",PrimitiveType.Cube,world.transform,new Vector3(-5,.8f,18),new Vector3(3,1.6f,1.2f),building,true);Make("Street barrier right",PrimitiveType.Cube,world.transform,new Vector3(5,.8f,37),new Vector3(3,1.6f,1.2f),building,true);Make("Street barrier center",PrimitiveType.Cube,world.transform,new Vector3(0,.7f,51),new Vector3(2.4f,1.4f,1.1f),building,true);
        GameObject player=new GameObject("PlayerController");player.transform.SetPositionAndRotation(new Vector3(0,1,0),Quaternion.identity);CharacterController cc=player.AddComponent<CharacterController>();cc.height=2;cc.radius=.48f;PlayerController pc=player.AddComponent<PlayerController>();GameObject capsule=GameObject.CreatePrimitive(PrimitiveType.Capsule);capsule.name="Capsule";capsule.transform.SetParent(player.transform,false);capsule.transform.localPosition=Vector3.zero;Object.DestroyImmediate(capsule.GetComponent<Collider>());SerializedObject pso=new SerializedObject(pc);pso.FindProperty("playerVisual").objectReferenceValue=capsule.transform;pso.FindProperty("moveSpeed").floatValue=5;pso.ApplyModifiedPropertiesWithoutUndo();
        GameObject camObj=new GameObject("Main Camera");camObj.tag="MainCamera";Camera cam=camObj.AddComponent<Camera>();cam.fieldOfView=75;cam.farClipPlane=200;camObj.AddComponent<AudioListener>();SerializedObject cso=new SerializedObject(pc);cso.FindProperty("cameraPivot").objectReferenceValue=camObj.transform;cso.ApplyModifiedPropertiesWithoutUndo();
        Light key=new GameObject("Alley Blue Fill").AddComponent<Light>();key.type=LightType.Directional;key.color=new Color32(104,142,205,255);key.intensity=.55f;key.transform.rotation=Quaternion.Euler(35,-25,0);RenderSettings.ambientMode=UnityEngine.Rendering.AmbientMode.Flat;RenderSettings.ambientLight=new Color32(34,38,58,255);RenderSettings.fog=true;RenderSettings.fogColor=new Color32(26,31,48,255);RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.006f;
        Vector3[] cp={new Vector3(-6,.75f,11),new Vector3(6,.75f,24),new Vector3(-6,.75f,38),new Vector3(5,.75f,49),new Vector3(-2,.75f,31)};Transform[] caches=new Transform[cp.Length];for(int i=0;i<cp.Length;i++){GameObject c=Make("Data Drive "+(i+1),PrimitiveType.Cube,world.transform,cp[i],new Vector3(.8f,.8f,.8f),gold,false);c.transform.rotation=Quaternion.Euler(0,45,45);caches[i]=c.transform;Make("Drive pedestal",PrimitiveType.Cylinder,world.transform,new Vector3(cp[i].x,.08f,cp[i].z),new Vector3(1.35f,.12f,1.35f),cyan,false);Label(world.transform,"DATA "+(i+1),cp[i]+Vector3.up*1.1f,cyan.color);}
        Vector3[] zp={new Vector3(0,.15f,15),new Vector3(1,.15f,30),new Vector3(-1,.15f,44)};Transform[] zones=new Transform[zp.Length];for(int i=0;i<zp.Length;i++){GameObject z=Make("Security Scan Zone "+(i+1),PrimitiveType.Cylinder,world.transform,zp[i],new Vector3(5.2f,.08f,5.2f),red,false);zones[i]=z.transform;Make("Scan beacon",PrimitiveType.Cylinder,world.transform,zp[i]+Vector3.up*.18f,new Vector3(.34f,.5f,.34f),pink,false);}
        GameObject exit=Make("Extraction Zone",PrimitiveType.Cylinder,world.transform,new Vector3(0,.12f,64),new Vector3(4.2f,.15f,4.2f),green,false);Label(world.transform,"EXTRACT",exit.transform.position+Vector3.up*.6f,new Color(.4f,1,.65f));Text status,progress,timer;BuildHud(out status,out progress,out timer);NeonCourierMission mission=new GameObject("Neon Courier Mission").AddComponent<NeonCourierMission>();mission.Configure(player.transform,caches,zones,exit.transform,status,progress,timer);
        AudioSource ambience=new GameObject("Level 3 — Neon Alley Music").AddComponent<AudioSource>();ambience.clip=AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/audio/FreshmanSound-Fear.mp3");ambience.loop=true;ambience.playOnAwake=true;ambience.spatialBlend=0;ambience.volume=.28f;
        EditorSceneManager.SaveScene(scene,ScenePath);AddBuildScene("Assets/Scenes/SampleScene.unity");AddBuildScene("Assets/Scenes/Level2_DotCircuit.unity");AddBuildScene(ScenePath);ConfigureLevelTwoTransition();Selection.activeGameObject=player;
    }
    private static void ConfigureLevelTwoTransition()
    {
        const string level2Path = "Assets/Scenes/Level2_DotCircuit.unity";
        Scene level2 = SceneManager.GetSceneByPath(level2Path);
        if (!level2.IsValid() || !level2.isLoaded) level2 = EditorSceneManager.OpenScene(level2Path, OpenSceneMode.Additive);
        foreach (DotCircuitPuzzle puzzle in Object.FindObjectsByType<DotCircuitPuzzle>(FindObjectsInactive.Include, FindObjectsSortMode.None))
        {
            if (puzzle.gameObject.scene.path != level2Path) continue;
            SerializedObject settings = new SerializedObject(puzzle);
            settings.FindProperty("nextSceneName").stringValue = "Level3_NeonCourier";
            settings.ApplyModifiedProperties();
            EditorUtility.SetDirty(puzzle);
        }
        EditorSceneManager.SaveScene(level2);
    }
    private static void AddBuildScene(string path){if(!File.Exists(path))return;EditorBuildSettingsScene[] s=EditorBuildSettings.scenes;if(!s.Any(x=>x.path==path))EditorBuildSettings.scenes=s.Concat(new[]{new EditorBuildSettingsScene(path,true)}).ToArray();}
    private static void BuildHud(out Text status,out Text progress,out Text timer){GameObject go=new GameObject("Level 3 HUD",typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));Canvas c=go.GetComponent<Canvas>();c.renderMode=RenderMode.ScreenSpaceOverlay;CanvasScaler sc=go.GetComponent<CanvasScaler>();sc.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;sc.referenceResolution=new Vector2(1920,1080);sc.matchWidthOrHeight=.5f;GameObject panel=new GameObject("Mission Brief Panel",typeof(RectTransform),typeof(Image));panel.transform.SetParent(go.transform,false);RectTransform pr=panel.GetComponent<RectTransform>();pr.anchorMin=pr.anchorMax=new Vector2(0,1);pr.pivot=new Vector2(0,1);pr.anchoredPosition=new Vector2(25,-25);pr.sizeDelta=new Vector2(650,218);panel.GetComponent<Image>().color=new Color(.015f,.025f,.055f,.9f);Text h=TextAt(panel.transform,"LEVEL 3 — NEON COURIER",new Vector2(18,-12),new Vector2(615,30),21,new Color(.2f,.9f,1));h.fontStyle=FontStyle.Bold;status=TextAt(panel.transform,"",new Vector2(18,-48),new Vector2(615,122),15,Color.white);progress=TextAt(panel.transform,"DRIVES 0/4 | ALERTS 0/2",new Vector2(18,-177),new Vector2(420,26),15,new Color(.75f,.9f,.95f));timer=TextAt(panel.transform,"TIME 75s",new Vector2(470,-177),new Vector2(160,26),15,new Color(1,.68f,.38f));}
    private static Text TextAt(Transform parent,string value,Vector2 pos,Vector2 size,int fontSize,Color color){GameObject g=new GameObject("Mission HUD Text",typeof(RectTransform),typeof(Text));g.transform.SetParent(parent,false);RectTransform r=g.GetComponent<RectTransform>();r.anchorMin=r.anchorMax=new Vector2(0,1);r.pivot=new Vector2(0,1);r.anchoredPosition=pos;r.sizeDelta=size;Text t=g.GetComponent<Text>();t.font=Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");t.text=value;t.fontSize=fontSize;t.color=color;t.alignment=TextAnchor.MiddleLeft;t.horizontalOverflow=HorizontalWrapMode.Wrap;t.verticalOverflow=VerticalWrapMode.Overflow;return t;}
    private static void Label(Transform parent,string text,Vector3 pos,Color color){GameObject g=new GameObject(text,typeof(TextMesh));g.transform.SetParent(parent,true);g.transform.position=pos;g.transform.rotation=Quaternion.Euler(90,0,0);TextMesh t=g.GetComponent<TextMesh>();t.text=text;t.anchor=TextAnchor.MiddleCenter;t.alignment=TextAlignment.Center;t.characterSize=.28f;t.fontSize=48;t.color=color;}
    private static GameObject Make(string name,PrimitiveType type,Transform parent,Vector3 pos,Vector3 scale,Material mat,bool collider){GameObject g=GameObject.CreatePrimitive(type);g.name=name;g.transform.SetParent(parent,true);g.transform.SetPositionAndRotation(pos,Quaternion.identity);g.transform.localScale=scale;Renderer r=g.GetComponent<Renderer>();if(r)r.sharedMaterial=mat;if(!collider){Collider c=g.GetComponent<Collider>();if(c)Object.DestroyImmediate(c);}return g;}
    private static Material Lit(string name,Color color,Color? emission=null){string path=Mats+"/"+name+".mat";Material m=AssetDatabase.LoadAssetAtPath<Material>(path);if(m==null){Shader s=Shader.Find("Universal Render Pipeline/Lit");if(s==null)s=Shader.Find("Standard");m=new Material(s);AssetDatabase.CreateAsset(m,path);}m.color=color;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",color);if(emission.HasValue){m.EnableKeyword("_EMISSION");if(m.HasProperty("_EmissionColor"))m.SetColor("_EmissionColor",emission.Value*2);}EditorUtility.SetDirty(m);return m;}
    private static void EnsureFolder(string path){if(AssetDatabase.IsValidFolder(path))return;string parent=Path.GetDirectoryName(path)?.Replace('\\','/');if(!AssetDatabase.IsValidFolder(parent))EnsureFolder(parent);AssetDatabase.CreateFolder(parent,Path.GetFileName(path));}
}
